import{t as e}from"./utils-COoNfFoj.js";var t={slug:`ben-meer`,influencerName:`Ben Meer`,influencerHandle:`@benmeer`,influencerAvatarUrl:`${e}/ben-meer-avatar.png`,heroDescription:`I’ve been manually tracking metrics like sleep, deep work, and steps for years because I believe self-tracking is a cheat code for energy and personal development and I’ve always dreamed of having one dashboard that auto-populates everything in one place instead of logging it all by hand.`,assetTitle:`Life Dashboard`,screenshotUrl:`${e}/ben-meer.png`,remixUrl:`https://www.perplexity.ai/computer/a/ben-meer-life-dashboard-QrSdgDd4TCCAwDg93jAHBw`,promptTitle:`Try Ben's prompt`,promptText:`Build a robust, tool-driven “Life Dashboard” that goes beyond a simple concept into a functional, interactive system (e.g., dashboard or generator). The goal is to automatically aggregate and visualize personal data—such as screen time, deep work, steps, nutrition, and water intake—in real time, showing daily progress and longer-term trends without manual input. Inspired by existing self-tracking ideas and example dashboards (in terms of depth and interactivity, not topic), the tool should feel comprehensive, dynamic, and actionable. Before building, clarify requirements and outline a plan for the ideal structure, data integrations, and user experience.`};export{t as default};
